list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool being invoked
    "previous_tool_calls": list,          # list of tool names already called in this episode
    "analysis_result": dict,              # result from analyze_transaction_pattern (if any)
    "customer_info_retrieved": bool,      # True if get_customer_info succeeded earlier
    "inquiry_content": str,               # text that will be sent to the relationship manager
    "response_content": str,              # text that will be sent to the customer
    "contains_aml_details": bool,         # True if the supplied text mentions AML investigation info
    # Additional generic arguments can be added as needed
}

# 2. Policy constants
HIGH_RISK_TOOLS = {"submit_str", "close_alert"}
MEDIUM_RISK_TOOLS = {"contact_relationship_manager", "generate_customer_response"}
ALWAYS_ALLOWED = {
    "get_alert_details",
    "analyze_transaction_pattern",
    "get_customer_info",
    "escalate_alert",
}
REQUIRED_PREV_FOR_HIGH = {"get_alert_details", "analyze_transaction_pattern"}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing required argument: tool_name"

    # Tools that are always allowed
    if tool in ALWAYS_ALLOWED:
        return True, f"Tool '{tool}' is always allowed."

    # Helper: check that required previous calls are present
    prev_calls = arguments.get("previous_tool_calls")
    if not isinstance(prev_calls, list):
        return False, "Missing or invalid 'previous_tool_calls' list."

    missing_prev = REQUIRED_PREV_FOR_HIGH - set(prev_calls)
    # ---------- High‑risk tools ----------
    if tool in HIGH_RISK_TOOLS:
        if missing_prev:
            return False, f"High‑risk tool '{tool}' requires prior calls: {missing_prev}."

        analysis = arguments.get("analysis_result")
        if not isinstance(analysis, dict):
            return False, f"High‑risk tool '{tool}' requires a structured 'analysis_result'."

        if tool == "submit_str":
            if not analysis.get("suspicious_finding"):
                return False, "submit_str denied: analysis does not indicate a suspicious finding."
            return True, "submit_str allowed: required prior calls present and suspicious finding confirmed."

        if tool == "close_alert":
            if not analysis.get("cleared"):
                return False, "close_alert denied: analysis does not indicate the alert is cleared."
            return True, "close_alert allowed: required prior calls present and alert cleared."

    # ---------- Medium‑risk tools ----------
    if tool == "contact_relationship_manager":
        if not arguments.get("customer_info_retrieved"):
            return False, "contact_relationship_manager denied: customer info not retrieved."
        if arguments.get("contains_aml_details"):
            return False, "contact_relationship_manager denied: inquiry contains AML investigation details."
        return True, "contact_relationship_manager allowed: customer info retrieved and no AML details in inquiry."

    if tool == "generate_customer_response":
        if arguments.get("contains_aml_details"):
            return False, "generate_customer_response denied: response contains AML investigation details."
        return True, "generate_customer_response allowed: response free of AML details."

    # Any other tool not explicitly covered is allowed
    return True, f"Tool '{tool}' is not subject to additional restrictions and is allowed."

